@@ -0,0 +1,36 @@
+import { memo } from "react";
+import { cleanup, render } from "@testing-library/react";
+import { afterEach, expect, it, vi } from "vitest";
+import { EditorContextProvider, useEditorContext } from "./editor-context";
+
+afterEach(cleanup);
+
+it("keeps editor consumers stable when their session, task, and activity stay unchanged", () => {
+  const observed = vi.fn();
+  const Consumer = memo(function Consumer() {
+    observed(useEditorContext());
+    return null;
+  });
+  const child = <Consumer />;
+  const value: ReturnType<typeof useEditorContext> = {
+    sessionId: "session",
+    taskId: "task",
+    detailActive: true,
+  };
+  const draw = (next = value) => (
+    <EditorContextProvider value={{ ...next }}>{child}</EditorContextProvider>
+  );
+  const view = render(draw());
+  for (let tick = 0; tick < 20; tick++) view.rerender(draw());
+  expect(observed).toHaveBeenCalledTimes(1);
+  for (const next of [
+    { ...value, sessionId: "next-session" },
+    { ...value, taskId: "next-task" },
+    { ...value, detailActive: false },
+    { sessionId: null, taskId: null, detailActive: true },
+  ]) {
+    view.rerender(draw(next));
+    expect(observed).toHaveBeenLastCalledWith(next);
+  }
+  expect(observed).toHaveBeenCalledTimes(5);
+});
