@@ -0,0 +1,113 @@
+import { memo } from "react";
+import { act, cleanup, render } from "@testing-library/react";
+import { afterEach, describe, expect, it, vi } from "vitest";
+import { sessionId, taskId, type Message, type TaskSession } from "@/lib/types/http";
+import { claimSessionRecovery } from "@/hooks/domains/session/session-recovery-pending";
+import { SessionRecoveryProvider, useSessionComposerRecovery } from "./session-recovery-context";
+
+vi.mock("../task-launch-error-context", () => ({ useTaskLaunchErrorContext: () => null }));
+afterEach(cleanup);
+const session: TaskSession = {
+  id: sessionId("session"),
+  task_id: taskId("task"),
+  state: "RUNNING",
+  started_at: "2026-10-23T10:00:00Z",
+  updated_at: "2026-10-23T10:00:00Z",
+};
+
+function probe() {
+  const observed = vi.fn();
+  const Consumer = memo(function Consumer({ id }: { id: string }) {
+    observed(useSessionComposerRecovery(id));
+    return null;
+  });
+  return { observed, Consumer };
+}
+
+describe("composer recovery subscriptions", () => {
+  it("does not notify a healthy composer when only its transcript or session timestamp changes", () => {
+    const { observed, Consumer } = probe();
+    const child = <Consumer id="session" />;
+    const draw = (tick: number) => (
+      <SessionRecoveryProvider
+        enabled
+        taskId="task"
+        session={{ ...session, updated_at: String(tick) }}
+        messages={[{ id: String(tick), content: String(tick) } as Message]}
+      >
+        {child}
+      </SessionRecoveryProvider>
+    );
+    const view = render(draw(0));
+    for (let tick = 1; tick <= 20; tick++) view.rerender(draw(tick));
+    expect(observed).toHaveBeenCalledTimes(1);
+    expect(observed).toHaveBeenLastCalledWith(
+      expect.objectContaining({ sessionId: "session", model: null, pending: null }),
+    );
+  });
+
+  it("publishes recovery, loading, callback, and enabled changes", () => {
+    const { observed, Consumer } = probe();
+    const child = <Consumer id="session" />;
+    const callback = vi.fn();
+    const draw = (
+      current: TaskSession,
+      enabled = true,
+      loading = false,
+      onDeliveryReconciled?: () => void,
+    ) => (
+      <SessionRecoveryProvider
+        enabled={enabled}
+        taskId="task"
+        session={current}
+        messages={[]}
+        messagesLoading={loading}
+        onDeliveryReconciled={onDeliveryReconciled}
+      >
+        {child}
+      </SessionRecoveryProvider>
+    );
+    const view = render(draw(session));
+    view.rerender(draw(session, true, false, callback));
+    expect(observed).toHaveBeenLastCalledWith(
+      expect.objectContaining({ onDeliveryReconciled: callback }),
+    );
+    const failed: TaskSession = { ...session, state: "FAILED", error_message: "Agent exited" };
+    view.rerender(draw(failed));
+    expect(observed).toHaveBeenLastCalledWith(
+      expect.objectContaining({
+        model: expect.objectContaining({ summary: "Agent exited", loading: false }),
+      }),
+    );
+    view.rerender(draw(failed, true, true));
+    expect(observed).toHaveBeenLastCalledWith(
+      expect.objectContaining({ model: expect.objectContaining({ loading: true }) }),
+    );
+    view.rerender(draw(failed, false));
+    expect(observed).toHaveBeenLastCalledWith(null);
+  });
+
+  it("publishes pending recovery and excludes a different session owner", () => {
+    const { observed, Consumer } = probe();
+    const child = <Consumer id="session" />;
+    const draw = (current: TaskSession) => (
+      <SessionRecoveryProvider enabled taskId="task" session={current} messages={[]}>
+        {child}
+      </SessionRecoveryProvider>
+    );
+    const view = render(draw(session));
+    let release: (() => void) | null = null;
+    try {
+      act(() => {
+        release = claimSessionRecovery("task\u0000session", "resume");
+      });
+      expect(observed).toHaveBeenLastCalledWith(expect.objectContaining({ pending: "resume" }));
+      act(() => release?.());
+      expect(observed).toHaveBeenLastCalledWith(expect.objectContaining({ pending: null }));
+      view.rerender(draw({ ...session, id: sessionId("replacement") }));
+      expect(observed).toHaveBeenLastCalledWith(null);
+    } finally {
+      act(() => release?.());
+    }
+  });
+});
